#include "magick/studio.h"
#include "magick/magick.h"

size_t RegisterMPCImage(void)
{
  MagickInfo
    *magick_info;

  MagickBooleanType
    status;

  magick_info = AcquireMagickInfo("MPC", "MPC", "Magick Persistent Cache");
  magick_info->description = ConstantString("Magick Persistent Cache");
  magick_info->module = ConstantString("MPC");
  magick_info->decoder = (DecoderHandler) ReadMPCImage;
  magick_info->encoder = (EncoderHandler) WriteMPCImage;
  magick_info->seekable = MagickTrue;
  magick_info->stealth = MagickTrue;
  status = RegisterMagickInfo(magick_info);
  if (status == MagickFalse)
    magick_info = DestroyMagickInfo(magick_info);
  return sizeof(*magick_info);
}
